function avatarImage(img){
  const c=img.crop;
  const style=c?`position:absolute;max-width:none;width:${100/c[2]}%;height:${100/c[3]}%;left:${-100*c[0]/c[2]}%;top:${-100*c[1]/c[3]}%;object-fit:fill`:`object-position:${esc(img.position||'50% 35%')}`;
  return `<img src="${esc(img.local||img.url)}" alt="" loading="lazy" style="${style}">`;
}
function licenseMarkup(img){
  let href=img.licenseUrl;
  if(!href){const cc=(img.license||'').match(/CC[ -]BY([ -]SA)?[ -]?(\d\.\d)/i);if(cc)href=`https://creativecommons.org/licenses/by${cc[1]?'-sa':''}/${cc[2]}/`;else if(/CC0/i.test(img.license||''))href='https://creativecommons.org/publicdomain/zero/1.0/';}
  return href?external(href,img.license):esc(img.license);
}

