function renderAtlas(){const s=stats();$('#main').innerHTML=`<section class="atlas-intro"><div><span class="eyebrow">A JOURNEY THROUGH THE SACRED WORLD</span><h1>在大地上，寻找诸神的回声。</h1><p>从创世的第一缕光，到文明深处的想象。<br>沿着地图，读懂一个神话如何理解世界。</p></div><div class="intro-stats"><div><strong>${state.data.length}</strong><span>文化与传统分区</span></div><div><strong>${s.entities}</strong><span>神祇 · 英雄 · 异兽</span></div><div><strong>${s.artifacts}</strong><span>法宝 · 圣物 · 象征</span></div></div></section><section class="atlas-workspace" aria-label="神话世界地图"><div class="cartography"><div class="map-toolbar"><button data-mapmode="flat" class="${state.mapMode==='flat'?'active':''}">平面图谱</button><button data-mapmode="globe" class="${state.mapMode==='globe'?'active':''}">立体地球</button></div><span class="map-tip">TERRA INCOGNITA · MYTHOS</span><div id="map-surface"></div><div class="compass"><img src="assets/emblem.svg" alt="指北罗盘"></div><div class="map-controls"><button data-action="map-plus" aria-label="放大地图">+</button><button data-action="map-minus" aria-label="缩小地图">−</button><button data-action="map-reset" aria-label="复位地图">复位</button></div><div class="map-meta"><span>✦ 点击地标，进入一个世界</span><span>文化区域 / 文学创作地 · 非唯一发源点<br>大陆轮廓 / NATURAL EARTH</span></div></div><aside id="atlas-preview" class="atlas-preview" aria-label="选中传统预览"></aside></section><div class="filter-bar"><span class="eyebrow">CHOOSE YOUR CHAPTER / 选择一段旅程</span>${[[0,'全部传统'],[3,'深度研读'],[2,'专题探索'],[1,'简明导览'],[4,'现代文学']].map(([v,n])=>`<button class="pill ${state.filter===v?'active':''}" data-filter="${v}">${n}</button>`).join('')}</div><section class="tradition-grid" id="tradition-grid" aria-label="传统目录"></section>`;renderPreview();renderTraditionCards();renderMap()}
function renderPreview(id=state.selected){const t=tradition(id)||state.data[0];state.selected=t.id;$('#atlas-preview').innerHTML=`<div class="preview-top"><span class="eyebrow">FEATURED CHAPTER</span><span class="count-label"><i class="tier-dot d${t.depth}"></i>${t.nature==='modern-literary'?'现代文学专题':depths[t.depth]}</span></div><div class="preview-art">${t.images?.length?imageMarkup(t.images[0]):`<div class="symbol-art">${icons[t.id]||'✦'}</div>`}<span class="art-label">${esc(t.images?.[0]?.title||t.en)}</span></div><span class="eyebrow">${esc(t.en)}</span><h2>${esc(titleShort(t))}</h2><p class="summary">${esc(t.tagline||t.summary.slice(0,80))}</p><div class="preview-numbers"><span><strong>${t.entities.length}</strong>位主体</span><span><strong>${t.events.length}</strong>个故事</span><span><strong>${t.artifacts.length}</strong>件物品</span></div><button class="button-primary" data-go="${t.id}">展开这一卷 <span>↗</span></button>`;$$('.map-marker').forEach(m=>m.classList.toggle('selected',m.dataset.id===t.id))}
