const mapNames={'china-early':'中国 · 上古','china-buddhist':'汉传佛教','china-daoist':'道教',egypt:'埃及',norse:'北欧','greco-roman':'希腊 · 罗马',hebrew:'希伯来',arthurian:'亚瑟王',maya:'玛雅',aztec:'阿兹特克',cthulhu:'克苏鲁 · 文学',japan:'日本',hindu:'印度教',inca:'印加',mesopotamia:'美索不达米亚',persia:'波斯',celtic:'凯尔特',slavic:'斯拉夫'};
