function renderMap(){mapCleanup();if(state.mapMode==='globe'){renderGlobe();return}const grid=[];for(let lon=-180;lon<=180;lon+=30){const a=geoPoint(lon,80),b=geoPoint(lon,-60);grid.push(`<path d="M${a}L${b}"/>`)}for(let lat=-60;lat<=80;lat+=20){const a=geoPoint(-180,lat),b=geoPoint(180,lat);grid.push(`<path d="M${a}L${b}"/>`)}$('#map-surface').innerHTML=`<svg class="world-map" id="world-map" viewBox="0 0 1120 520" aria-label="可缩放和拖动的世界神话地图"><g id="map-view"><g class="map-grid">${grid.join('')}</g><g class="map-land">${landSvg()}</g><text class="map-label" x="200" y="200">NORTH AMERICA</text><text class="map-label" x="296" y="390">SOUTH AMERICA</text><text class="map-label" x="555" y="140">EUROPE</text><text class="map-label" x="585" y="318">AFRICA</text><text class="map-label" x="790" y="170">ASIA</text><text class="map-label" x="880" y="400">OCEANIA</text>${mapMarkers()}</g></svg>`;updateMapTransform();const svg=$('#world-map');let drag=null,moved=false;svg.onpointerdown=e=>{if(e.target.closest('.map-marker'))return;drag={x:e.clientX,y:e.clientY,px:state.panX,py:state.panY};moved=false;svg.setPointerCapture(e.pointerId)};svg.onpointermove=e=>{if(drag){const f=1120/svg.clientWidth;state.panX=drag.px+(e.clientX-drag.x)*f;state.panY=drag.py+(e.clientY-drag.y)*f;moved=true;updateMapTransform()}};svg.onpointerup=()=>{drag=null};svg.onpointercancel=()=>{drag=null};svg.onwheel=e=>{if(e.ctrlKey){e.preventDefault();state.mapZoom=Math.max(.8,Math.min(3.5,state.mapZoom*(e.deltaY<0?1.1:.9)));updateMapTransform()}};mapCleanup=()=>{svg.onpointerdown=svg.onpointermove=svg.onpointerup=svg.onwheel=null}}
