function renderTradition(t,tab){const readCount=tabs.filter(([id])=>state.read.includes(`${t.id}/${id}`)).length;$('#main').innerHTML=`<div class="book-page"><div class="detail-layout"><aside class="detail-sidebar"><a class="back-link" href="#atlas">← 返回世界图谱</a><div class="sidebar-label eyebrow">THE CHAPTERS / 文明之卷</div><nav class="tradition-nav" aria-label="神话传统">${state.data.map(x=>`<a href="#tradition/${x.id}/worldview" class="${x.id===t.id?'active':''}">${esc(x.name)}<small>${x.depth===3?'◆':x.depth===2?'◇':'·'}</small></a>`).join('')}</nav><div class="reading-progress">本卷阅读进度 <span class="gold">${readCount} / ${tabs.length}</span><div class="progress-track"><span style="width:${readCount/tabs.length*100}%"></span></div>读完后可在章节底部做标记。</div></aside><article class="detail-main"><a class="back-link" href="#atlas">世界图谱 / ${esc(t.region)} / ${esc(t.name)}</a><div class="detail-hero"><div><span class="eyebrow">${esc(t.en)} · ${t.nature==='modern-literary'?'现代文学专题':depths[t.depth]}</span><h1>${esc(t.name)}</h1><p>${esc(t.tagline)}</p><div class="detail-meta"><span>${esc(t.period)}</span><span>${t.entities.length} 位主体 · ${t.relations.length} 条关系 · ${t.events.length} 个事件 · ${t.artifacts.length} 件物品</span></div></div><div class="hero-symbol" aria-hidden="true">${icons[t.id]||'✦'}</div></div>${t.nature==='modern-literary'?'<aside class="literary-banner"><span>✧ 现代文学 · 虚构体系</span><p>本卷讨论20世纪作者创造、后世持续扩写的文学世界。地图标记文学创作地；它与古代神话、地方口传及活态宗教的形成方式不同。原作、后续作者与游戏设定分别核读。</p></aside>':''}<div class="chapter-tabs" role="navigation" aria-label="本卷章节">${tabs.map(([id,name])=>`<a href="#tradition/${t.id}/${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${name}${state.read.includes(`${t.id}/${id}`)?' ·':''}</a>`).join('')}</div><section id="chapter-content"></section><div class="chapter-end"><span>章节的阅读记录保存在当前浏览器。</span><button class="chapter-read ${state.read.includes(`${t.id}/${tab}`)?'read':''}" data-read="${t.id}/${tab}">${state.read.includes(`${t.id}/${tab}`)?'✓ 已读这一章':'○ 标记这一章已读'}</button></div></article></div></div>`;({worldview:renderWorldview,history:renderHistory,entities:renderEntities,relations:renderRelations,events:renderEvents,artifacts:renderArtifacts,sources:renderSources}[tab])(t)}
