function renderWorldview(t){
  $('#chapter-content').innerHTML=`<div class="chapter-heading"><div><span class="eyebrow">01 / UNDERSTANDING THE COSMOS</span><h2>这个世界，如何运转？</h2></div><span class="count-label">点击卡片，展开解读</span></div><p class="worldview-intro">${esc(t.summary)}</p><div class="concept-map" aria-label="世界观概念索引">${(cosmos[t.id]||[]).map(([name,sub],i)=>`${i?'<span class="concept-arrow">—</span>':''}<div class="concept-node"><div class="concept-orb">${['天','界','人'][i]}</div><strong>${esc(name)}</strong><small>${esc(sub)}</small></div>`).join('')}</div><div class="worldview-cards">${t.worldview.map((w,i)=>`<details class="worldview-card compact-card"><summary><span class="number">${String(i+1).padStart(2,'0')} —</span><h3>${esc(w.title)}</h3><p class="card-teaser">${esc(w.text.slice(0,72))}${w.text.length>72?'…':''}</p><span class="fold-cue">展开解读 ＋</span></summary><div class="card-body"><p>${esc(w.text)}</p>${sourceLink(t,w.source)}</div></details>`).join('')}</div>${groupSection(t)}${t.quotes.length?readingFold('原典摘句',t.quotes.slice(0,2).map(q=>quoteCard(t,q)).join(''),'与文本对读'):''}${readingFold('版本边界与阅读提示',`<p class="prose">概念索引是阅读辅助，不代表唯一的宇宙层级。</p><ul class="caution-list">${t.cautions.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`)}${readingFold('建议阅读路线',`<div class="reading-route">${t.reading.map((r,i)=>`<div class="reading-step"><b>${String(i+1).padStart(2,'0')}</b><div><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p></div></div>`).join('')}</div>`,`${t.reading.length} 个起点`)}`;
}

function quoteCard(t,q){return `<div class="quote-card"><span class="quote-mark">“</span><div><blockquote>${esc(q.text)}</blockquote><div class="quote-locator">${esc(q.locator)}</div><p>${esc(q.note)}</p>${sourceLink(t,q.source,'前往原文核读')}</div></div>`}
function renderHistory(t){$('#chapter-content').innerHTML=`<div class="chapter-heading"><div><span class="eyebrow">02 / MYTH & THE LIVED WORLD</span><h2>神话之外，也在神话之中。</h2><p>点击主题，阅读历史语境与现实联系。</p></div></div><div class="history-folds">${t.history.map((h,i)=>`<details class="reading-fold"><summary><span><b class="fold-number">${String(i+1).padStart(2,'0')}</b>${esc(h.title)}</span><span class="fold-cue">展开 ＋</span></summary><div class="fold-content"><p class="prose">${esc(h.text)}</p>${sourceLink(t,h.source)}</div></details>`).join('')}</div>${t.images.length?readingFold('从图像与实物继续阅读',`<div class="gallery">${t.images.slice(0,2).map(galleryItem).join('')}</div>`):''}`}

function entityCard(t,e){return `<button class="entity-card" data-entity="${e.id}" data-tier="${e.tier}">${portraitMarkup(e)}${badge(e.tier)}<span class="entity-kind">${esc(e.kind)}</span><h3>${esc(e.name)}</h3><span class="alias">${esc(e.alias||e.domain)}</span><p>${esc(e.summary)}</p></button>`}
function renderEntities(t){$('#chapter-content').innerHTML=`<div class="chapter-heading"><div><span class="eyebrow">03 / GODS, HEROES & CREATURES</span><h2>诸神与众生</h2><p>分级表示本学习图谱中的叙事重要性，不是神力或宗教地位排名。</p></div><button class="button-outline" data-go="${t.id}" data-tab="relations">查看关系图 ↗</button></div><div class="toolbar"><label>重要性<select id="entity-tier"><option value="0">全部主体</option>${[1,2,3].map(i=>`<option value="${i}" ${state.entityTier===i?'selected':''}>${tiers[i]}主体</option>`).join('')}</select></label><input id="entity-search" type="search" placeholder="查找名称、别名、神职或故事…" value="${esc(state.entityQuery)}"><span id="entity-count" class="entity-count"></span></div><div class="entity-grid" id="entity-grid"></div>`;renderEntityGrid(t);$('#entity-tier').onchange=e=>{state.entityTier=+e.target.value;renderEntityGrid(t)};$('#entity-search').oninput=e=>{state.entityQuery=e.target.value;renderEntityGrid(t)}}
function renderEntityGrid(t){const q=state.entityQuery.trim().toLowerCase(),items=t.entities.filter(e=>(!state.entityTier||e.tier===state.entityTier)&&(!q||[e.name,e.alias,e.domain,e.summary,e.detail].join(' ').toLowerCase().includes(q))).sort((a,b)=>a.tier-b.tier);$('#entity-count').textContent=`${items.length} / ${t.entities.length} 位主体`;$('#entity-grid').innerHTML=items.length?items.map(e=>entityCard(t,e)).join(''):'<div class="empty-state">没有找到匹配的主体。可以换个关键词或切换重要性。</div>'}
function renderRelations(t){
  if(!t.groups.some(g=>g.id===state.graphGroup))state.graphGroup='';
  $('#chapter-content').innerHTML=`<div class="chapter-heading"><div><span class="eyebrow">04 / THREADS BETWEEN BEINGS & THINGS</span><h2>每一条线，都通向一个故事。</h2><p>点击节点阅读图文与原典。圆形为人物或生灵，方形为物件；大小区分重要性。</p></div></div><div class="toolbar"><label>显示范围<select id="graph-tier">${[1,2,3].map(i=>`<option value="${i}" ${state.graphTier===i?'selected':''}>${['','核心','核心 + 重要','全部（含扩展）'][i]}</option>`).join('')}</select></label><label>体系分组<select id="graph-group"><option value="">全部分组</option>${t.groups.map(g=>`<option value="${g.id}" ${state.graphGroup===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label><label class="graph-toggle"><input id="graph-objects" type="checkbox" ${state.graphObjects?'checked':''}>包含关联物件</label><button class="button-outline" data-action="graph-in" aria-label="放大关系图">＋</button><button class="button-outline" data-action="graph-out" aria-label="缩小关系图">−</button><button class="button-outline" id="graph-reset">复位</button></div><div class="graph-container"><div class="graph-legend"><span><i></i>核心</span><span><i></i>重要</span><span><i></i>扩展</span><span>◇ 物件</span></div><svg id="relation-graph" viewBox="0 0 1000 700" aria-label="${esc(t.name)}人物与物件关系图"></svg><div class="graph-status" id="graph-status"></div></div><details class="reading-fold graph-reading-note"><summary>图谱读法<span class="fold-cue">操作与关系说明 ＋</span></summary><div class="fold-content"><p class="prose">滚轮缩放、拖动平移、悬停聚焦。物件关联包括使用、制作、争夺或受其作用，详见条目。头像采用有来源的形象；没有可靠图像的节点保留文字。</p></div></details><details class="reading-fold"><summary>关系与版本索引<span class="fold-cue">逐条核读 ＋</span></summary><div class="fold-content"><div class="relation-list" id="relation-list"></div></div></details>`;
  $('#graph-tier').onchange=e=>{state.graphTier=+e.target.value;drawGraph(t)};
  $('#graph-group').onchange=e=>{state.graphGroup=e.target.value;drawGraph(t)};
  $('#graph-objects').onchange=e=>{state.graphObjects=e.target.checked;drawGraph(t)};
  $('#graph-reset').onclick=()=>drawGraph(t);drawGraph(t);
}

function drawGraph(t){
  graphCleanup();
  const group=t.groups.find(g=>g.id===state.graphGroup),members=group?new Set(group.members):null;
  const people=t.entities.filter(e=>e.tier<=state.graphTier&&(!members||members.has(e.id)));
  const peopleIds=new Set(people.map(e=>e.id));
  const objects=state.graphObjects?t.artifacts.filter(a=>a.tier<=state.graphTier&&(!members||a.owners.some(id=>peopleIds.has(id)))):[];
  for(const a of objects)for(const id of a.owners){const f=entityById(id);if(f&&!peopleIds.has(id)&&f.e.tier<=state.graphTier){people.push({...f.e,externalTradition:f.t.name});peopleIds.add(id)}}
  const nodes=[...people,...objects].map(e=>({...e,x:0,y:0})),nodeMap=new Map(nodes.map(e=>[e.id,e]));
  const edges=t.relations.filter(r=>nodeMap.has(r.from)&&nodeMap.has(r.to)).concat(objects.flatMap(a=>a.owners.filter(id=>peopleIds.has(id)).map(id=>({from:id,to:a.id,type:'关联物件',note:a.summary,source:a.sources[0],artifact:true}))));
  const scale=Math.max(1,Math.sqrt(nodes.length/50)),w=1000*scale,h=700*scale;
  for(const tier of [1,2,3]){const row=nodes.filter(n=>n.tier===tier),r=(tier===1?140:tier===2?240:310)*scale;row.forEach((n,i)=>{const a=i/row.length*Math.PI*2-Math.PI/2+(tier===2?.2:0);n.x=w/2+Math.cos(a)*r*1.25;n.y=h/2+Math.sin(a)*r*.88})}
  const radius=n=>n.tier===1?32:n.tier===2?23:16;
  for(let k=0;k<100;k++){for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=nodes[i],b=nodes[j];let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1,space=radius(a)+radius(b)+44;if(d<space){const f=(space-d)*.15;dx/=d;dy/=d;a.x-=dx*f;a.y-=dy*f;b.x+=dx*f;b.y+=dy*f}}nodes.forEach(n=>{n.x=Math.max(65,Math.min(w-65,n.x));n.y=Math.max(65,Math.min(h-65,n.y))})}
  const svg=$('#relation-graph');svg.dataset.maxWidth=w*1.6;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);
  svg.innerHTML=`<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="8" refY="4" orient="auto" markerUnits="userSpaceOnUse"><path d="M0,0L8,4L0,8" fill="none" stroke="#a1b5a0"/></marker></defs><g>${edges.map(r=>{const a=nodeMap.get(r.from),b=nodeMap.get(r.to),dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,ar=radius(a),br=radius(b);return `<path class="graph-edge ${r.artifact?'object-edge':''}" data-from="${r.from}" data-to="${r.to}" marker-end="url(#arrow)" d="M${a.x+dx/len*ar},${a.y+dy/len*ar} Q${(a.x+b.x)/2-dy*.06},${(a.y+b.y)/2+dx*.06} ${b.x-dx/len*(br+4)},${b.y-dy/len*(br+4)}"><title>${esc(a.name)} → ${esc(r.type)} → ${esc(b.name)}：${esc(r.note)}</title></path>`}).join('')}${nodes.map(n=>{const r=radius(n),img=avatarFor(n);return `<g class="graph-node ${n.isArtifact?'artifact-node':''}" tabindex="0" role="button" aria-label="${esc(n.name)}，${tiers[n.tier]}${n.isArtifact?'物件':'主体'}" data-entity="${n.id}" data-tier="${n.tier}" transform="translate(${n.x},${n.y})">${n.isArtifact?`<rect class="object-frame" x="${-r}" y="${-r}" width="${r*2}" height="${r*2}" rx="7"/>`:`<circle r="${r}"/>`}${img?`<foreignObject x="${-r+2}" y="${-r+2}" width="${2*r-4}" height="${2*r-4}"><div xmlns="http://www.w3.org/1999/xhtml" class="graph-avatar">${avatarImage(img)}</div></foreignObject>`:`<text class="graph-initial" text-anchor="middle" dominant-baseline="central">${esc(n.name.replace(/[《》·\s]/g,'').slice(0,1))}</text>`}<text text-anchor="middle" y="${r+19}">${esc(n.name.length>10?n.name.slice(0,10)+'…':n.name)}</text><title>${esc(n.name)}${n.externalTradition?' · 跨卷：'+esc(n.externalTradition):''} · ${esc(n.summary)}</title></g>`}).join('')}</g>`;
  $('#graph-status').textContent=`${people.length} 位主体 · ${objects.length} 件物品 · ${edges.length} 条关联`;
  $$('.graph-node',svg).forEach(g=>{const focus=()=>{const id=g.dataset.entity,linked=new Set([id]);edges.forEach(e=>{if(e.from===id||e.to===id){linked.add(e.from);linked.add(e.to)}});$$('.graph-node',svg).forEach(n=>n.classList.toggle('dim',!linked.has(n.dataset.entity)));$$('.graph-edge',svg).forEach(e=>e.classList.toggle('focus',e.dataset.from===id||e.dataset.to===id))};const reset=()=>{$$('.dim,.focus',svg).forEach(x=>x.classList.remove('dim','focus'))};g.onpointerenter=g.onfocus=focus;g.onpointerleave=g.onblur=reset});
  $('#relation-list').innerHTML=edges.map(r=>`<div class="relation-row"><div><button data-entity="${r.from}">${esc(nodeMap.get(r.from).name)}</button><span>— ${esc(r.type)} →</span><button data-entity="${r.to}">${esc(nodeMap.get(r.to).name)}</button></div><p>${esc(r.note)}</p>${sourceLink(t,r.source,'核对出处')}</div>`).join('')||'<div class="empty-state">当前范围没有已编录连线。可调整分组、重要性或物件开关。</div>';
  let box={x:0,y:0,w,h},drag=null;
  svg.onwheel=e=>{e.preventDefault();[box.x,box.y,box.w,box.h]=svg.getAttribute('viewBox').split(' ').map(Number);const width=Math.max(350,Math.min(w*1.6,box.w*(e.deltaY>0?1.12:.89))),height=width*.7;box.x+=(box.w-width)/2;box.y+=(box.h-height)/2;box.w=width;box.h=height;svg.setAttribute('viewBox',Object.values(box).join(' '))};
  svg.onpointerdown=e=>{if(e.target.closest('.graph-node'))return;[box.x,box.y,box.w,box.h]=svg.getAttribute('viewBox').split(' ').map(Number);drag={x:e.clientX,y:e.clientY,bx:box.x,by:box.y};svg.setPointerCapture(e.pointerId)};
  svg.onpointermove=e=>{if(drag){box.x=drag.bx-(e.clientX-drag.x)*box.w/svg.clientWidth;box.y=drag.by-(e.clientY-drag.y)*box.h/svg.clientHeight;svg.setAttribute('viewBox',Object.values(box).join(' '))}};
  svg.onpointerup=svg.onpointercancel=()=>drag=null;graphCleanup=()=>{svg.onwheel=svg.onpointerdown=svg.onpointermove=svg.onpointerup=svg.onpointercancel=null};
}

function renderEvents(t){$('#chapter-content').innerHTML=`<div class="chapter-heading"><div><span class="eyebrow">05 / STORIES THAT SHAPE A WORLD</span><h2>叙事与事件</h2><p>依本卷学习顺序排列；神话中的先后关系不是历史纪年。展开阅读版本与意义。</p></div></div><div class="toolbar"><label>重要性<select id="event-tier"><option value="0">全部事件</option>${[1,2,3].map(i=>`<option value="${i}" ${state.eventTier===i?'selected':''}>${tiers[i]}事件</option>`).join('')}</select></label></div><div class="event-list" id="event-list"></div>`;renderEventList(t);if(state.pendingEvent){const el=document.getElementById(`event-${state.pendingEvent}`);if(el){el.open=true;requestAnimationFrame(()=>el.scrollIntoView({behavior:'smooth',block:'center'}));}state.pendingEvent=null;}$('#event-tier').onchange=e=>{state.eventTier=+e.target.value;renderEventList(t)}}
function renderEventList(t){$('#event-list').innerHTML=t.events.filter(e=>!state.eventTier||e.tier===state.eventTier).map(e=>`<details class="event-card" id="event-${e.id}" data-tier="${e.tier}"><summary><div class="event-top">${badge(e.tier)}<h3>${esc(e.title)}</h3><span class="expand">＋</span></div><div class="era">${esc(e.era)}</div><p class="event-summary">${esc(e.summary)}</p></summary><div class="event-detail"><p>${esc(e.detail)}</p><div class="actor-links">${e.actors.map(id=>{const entity=entityById(id)?.e;return entity?`<button data-entity="${id}">${esc(entity.name)} ↗</button>`:''}).join('')}</div>${artifactLinks(t,e.id,true)}${itemGallery(e,'事件的视觉呈现')}${citationSection(t,e)}${sourceLink(t,e.source)}</div></details>`).join('')||'<div class="empty-state">这一分级暂无已编录事件。</div>'}
function galleryItem(img){const key=img.local||img.url;window.atlasImageIndex??=new Map();window.atlasImageIndex.set(key,img);return `<figure><button class="image-box" data-image="${esc(key)}" aria-label="放大：${esc(img.title)}">${imageMarkup(img)}<span class="image-enlarge">↗ 查看大图</span></button><figcaption>${img.role?`<span class="image-role">${imageRoles[img.role]||'图像资料'}</span>`:''}<h3>${esc(img.title)}</h3><details class="image-notes"><summary>图注与出处 ＋</summary><p>${esc(img.caption)}</p><small>${esc(img.credit)} · ${licenseMarkup(img)}${img.crop?' · 头像为原图显示裁切':''}</small>${external(img.pageUrl,'馆藏与图像来源')}</details></figcaption></figure>`}

function sourceCard(t,s){return `<article class="source-card"><span class="source-kind">${esc(s.kind)} · ${esc(t.name)}</span><h3>${esc(s.title)}</h3><div class="author">${esc(s.author)}</div><p>${esc(s.note)}</p>${external(s.url,'打开来源')}</article>`}
function renderSources(t){$('#chapter-content').innerHTML=`<div class="chapter-heading"><div><span class="eyebrow">07 / THE PRIMARY SOURCES</span><h2>回到文字，与图像。</h2><p>选择一组资料展开，逐条核读出处与说明。</p></div></div>${readingFold('原典摘句',t.quotes.map(q=>quoteCard(t,q)).join(''),`${t.quotes.length} 段`)}${readingFold('图像档案',`<div class="gallery">${t.images.map(galleryItem).join('')}</div>`,`${t.images.length} 件`)}${readingFold('参考书架',`<div class="source-grid">${t.sources.map(s=>sourceCard(t,s)).join('')}</div>`,`${t.sources.length} 个入口`)}${readingFold('如何使用这些资料','<p class="prose">原典用于核读叙事，馆藏与研究用于理解语境。旧译可能保留过时术语；图像创作年代不等于神话起源年代。每幅作品的图注与出处可单独展开。</p>')}`}

function openEntity(id){const found=entityById(id);if(!found)return;const {t,e}=found;if(e.isArtifact){openArtifact(t,e);return}const links=state.data.flatMap(x=>x.relations).filter(r=>r.from===id||r.to===id),events=state.data.flatMap(x=>x.events.map(e=>({...e,traditionId:x.id}))).filter(x=>x.actors.includes(id));$('#detail-content').innerHTML=`<div class="dialog-head"><span class="eyebrow">${esc(t.name)} / ${esc(e.kind)}</span><button data-close="detail-dialog" aria-label="关闭人物详情">×</button></div><article class="entity-sheet"><div class="sheet-title"><div>${badge(e.tier)}<h2>${esc(e.name)}</h2><p class="sheet-alias">${e.alias?esc(e.alias)+' · ':''}${esc(e.domain)}</p></div><button class="button-outline ${state.bookmarks.includes(id)?'active':''}" data-bookmark="${id}">${state.bookmarks.includes(id)?'◆ 已收藏':'◇ 加入书签'}</button></div><p class="sheet-summary">${esc(e.summary)}</p>${itemGallery(e)}<p class="prose">${esc(e.detail)}</p>${citationSection(t,e)}${artifactLinks(t,e.id)}${links.length?`<section class="sheet-section"><h3>与谁相连</h3><div class="sheet-links">${links.map(r=>{const other=entityById(r.from===id?r.to:r.from)?.e;return other?`<button data-entity="${other.id}">${portraitMarkup(other,'related-avatar')}${esc(other.name)}<span>${r.from===id?'→':'←'} ${esc(r.type)}</span></button>`:''}).join('')}</div><p class="controls-note">箭头按原始关系的方向标注；完整版本说明请看关系图谱。</p></section>`:''}${events.length?`<section class="sheet-section"><h3>出现在哪些故事中</h3><div class="sheet-links">${events.map(v=>`<button data-event="${v.id}" data-tradition="${v.traditionId||t.id}">${esc(v.title)}</button>`).join('')}</div></section>`:''}<details class="reading-fold"><summary>更多出处与阅读说明<span class="fold-cue">＋</span></summary><div class="fold-content">${(e.sources||[]).map(id=>{const s=t.sources.find(x=>x.id===id);return s?external(s.url,s.title,'sheet-source'):''}).join('')}<p>按所列文本的叙事范围阅读，异本中的关系、身份与经历可能不同。图像反映作品所属时代的诠释，不等于神话人物的历史肖像。</p></div></details></article>`;const d=$('#detail-dialog');if(!d.open)d.showModal();d.scrollTop=0}
function renderCompare(){const a=tradition(state.compare[0])||state.data[0],b=tradition(state.compare[1])||state.data[4];const select=(id,val)=>`<select id="${id}" aria-label="${id==='compare-a'?'左侧传统':'右侧传统'}">${state.data.map(t=>`<option value="${t.id}" ${t.id===val?'selected':''}>${esc(t.name)}</option>`).join('')}</select>`;const content=(t,kind)=>kind==='overview'?`<p>${esc(t.summary)}</p>`:kind==='cosmos'?t.worldview.slice(0,3).map(x=>`<h4>${esc(x.title)}</h4><p>${esc(x.text)}</p>${sourceLink(t,x.source)}<br><br>`).join(''):kind==='history'?t.history.slice(0,2).map(x=>`<h4>${esc(x.title)}</h4><p>${esc(x.text)}</p>${sourceLink(t,x.source)}<br><br>`).join(''):kind==='cautions'?t.cautions.map(x=>`<p>· ${esc(x)}</p>`).join(''):`<div class="actor-links">${t.entities.filter(e=>e.tier===1).slice(0,9).map(e=>`<button data-entity="${e.id}">${esc(e.name)}</button>`).join('')}</div>`;$('#main').innerHTML=`<div class="full-page"><div class="page-title"><span class="eyebrow">PARALLELS & DIFFERENCES</span><h1>让不同的世界，彼此照见。</h1><p>并置阅读创世、秩序、死亡与历史语境。相似的母题可能来自传播，也可能独立形成；这里只比较，不据相似性推定同源。</p></div><div class="comparison-select">${select('compare-a',a.id)}<span>与</span>${select('compare-b',b.id)}</div><div class="comparison-grid"><div class="compare-label">比较维度</div><div class="compare-head">${esc(a.name)}</div><div class="compare-head">${esc(b.name)}</div>${[['overview','整体视角'],['cosmos','世界的结构'],['entities','核心主体'],['history','历史联系'],['cautions','版本边界']].map(([id,label])=>`<div class="compare-label">${label}</div><div>${content(a,id)}</div><div>${content(b,id)}</div>`).join('')}</div><h2 class="subheading">沿着一个母题继续探索</h2><div class="motif-grid">${[{title:'洪水之后，如何重新开始？',text:'禹的治水、诺亚的方舟与美索不达米亚的洪水叙事，分别把问题引向秩序、盟约与人的生存。不要把治理洪水与灭世洪水当成同一种故事。',ids:['china-early','hebrew','mesopotamia']},{title:'死亡，是终点还是边界？',text:'埃及的死后转化、希腊的冥府与佛教的轮回，提出不同的问题。轮回中的再生不等于木乃伊文化的身体观念。',ids:['egypt','greco-roman','china-buddhist']},{title:'一个世界如何走向终局？',text:'诸神黄昏、印度宇宙周期与亚伯拉罕传统的末世观不能简单互换。注意毁灭、更新与时间形式的差别。',ids:['norse','hindu','hebrew']}].map((m,i)=>`<article class="motif-card"><span class="eyebrow">MOTIF 0${i+1}</span><h3>${m.title}</h3><p>${m.text}</p><div class="motif-links">${m.ids.map(id=>`<a href="#tradition/${id}/worldview">${esc(tradition(id)?.name||id)}</a>`).join('')}</div></article>`).join('')}</div></div>`;$('#compare-a').onchange=e=>{state.compare[0]=e.target.value;renderCompare()};$('#compare-b').onchange=e=>{state.compare[1]=e.target.value;renderCompare()}}
function renderLibrary(){const kinds=[...new Set(state.data.flatMap(t=>t.sources.map(s=>s.kind)))];$('#main').innerHTML=`<div class="full-page"><div class="page-title"><span class="eyebrow">THE READING ROOM</span><h1>原典书房</h1><p>从《山海经》到《埃达》，从泥版、纸草到后世文学。每一卷都有自己的年代、作者与声音。</p></div><div class="toolbar"><label>传统<select id="library-trad"><option value="all">所有传统</option>${state.data.map(t=>`<option value="${t.id}" ${state.libraryTrad===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>类型<select id="library-kind"><option value="all">所有来源</option>${kinds.map(k=>`<option value="${esc(k)}" ${state.libraryKind===k?'selected':''}>${esc(k)}</option>`).join('')}</select></label><input type="search" id="library-search" placeholder="搜索书名、作者、章节或关键词…" value="${esc(state.libraryQuery)}"><span class="entity-count" id="library-count"></span></div><div class="library-grid" id="library-grid"></div></div>`;renderLibraryGrid();$('#library-trad').onchange=e=>{state.libraryTrad=e.target.value;renderLibraryGrid()};$('#library-kind').onchange=e=>{state.libraryKind=e.target.value;renderLibraryGrid()};$('#library-search').oninput=e=>{state.libraryQuery=e.target.value;renderLibraryGrid()}}
function renderLibraryGrid(){const q=state.libraryQuery.trim().toLowerCase(),items=state.data.flatMap(t=>t.sources.map(s=>({t,s}))).filter(({t,s})=>(state.libraryTrad==='all'||t.id===state.libraryTrad)&&(state.libraryKind==='all'||s.kind===state.libraryKind)&&(!q||[s.title,s.author,s.note,t.name].join(' ').toLowerCase().includes(q)));$('#library-count').textContent=`${items.length} 个阅读入口`;$('#library-grid').innerHTML=items.length?items.map(({t,s})=>sourceCard(t,s)).join(''):'<div class="empty-state">没有匹配的来源，试试其他关键词。</div>'}
function renderNotebook(){const items=state.bookmarks.map(entityById).filter(Boolean);$('#main').innerHTML=`<div class="full-page"><div class="page-title"><span class="eyebrow">YOUR FIELD NOTES</span><h1>旅人的书签</h1><p>收藏令你停留的主体与物件，记下新的线索。书签、笔记与阅读进度只保存在这台设备的当前浏览器，可以导出留存。</p></div><div class="section-top"><span class="count-label">${items.length} 个书签 · ${state.read.length} 章已读</span><button class="button-outline" data-action="export-notes">导出学习记录 ↓</button></div><div class="notebook-grid">${items.length?items.map(({t,e})=>`<article class="notebook-item"><span class="eyebrow">${esc(t.name)}</span><h3>${esc(e.name)}</h3><p>${esc(e.summary)}</p><div class="notebook-actions"><button data-entity="${e.id}">继续阅读 ↗</button><button data-bookmark="${e.id}" aria-label="移除${esc(e.name)}的书签">移除</button></div></article>`).join(''):'<div class="empty-state">还没有书签。进入任一主体的详情，点击「加入书签」。<br><a class="source-link" href="#atlas">回到地图，开始探索 ↗</a></div>'}</div><div class="notes-area"><label for="learning-notes">我的学习札记</label><p>一个相似的母题、一处不同的版本，或一个想追问的问题。</p><textarea id="learning-notes" placeholder="例如：希腊与埃及的死后观念有哪些根本差别？">${esc(safeRead('myth-notes',''))}</textarea><div class="save-status" id="notes-status">${safeRead('myth-notes','')?'已读取本地笔记':'输入后自动保存'}</div></div></div>`;$('#learning-notes').oninput=e=>{if(saveLocal('myth-notes',e.target.value))$('#notes-status').textContent='已保存到当前浏览器'}}
function openSearch(){const d=$('#search-dialog');if(!d.open)d.showModal();$('#global-search').value='';renderSearch('');$('#global-search').focus()}
function renderSearch(query){const q=query.trim().toLowerCase();if(!q){$('#search-results').innerHTML='<div class="search-hint">可以搜索主体、物件、故事、传统或原典。<br>试试「女娲」「奥丁」「轮回」「洪水」「封神」。</div>';return}const results=[];for(const t of state.data){if([t.name,t.en,t.tagline,t.summary].join(' ').toLowerCase().includes(q))results.push({type:'tradition',id:t.id,title:t.name,label:'传统',text:t.tagline});for(const e of [...t.entities,...t.artifacts])if([e.name,e.alias,e.domain,e.kind,e.summary,e.detail].join(' ').toLowerCase().includes(q))results.push({type:'entity',id:e.id,title:e.name,label:t.name+' · '+(e.isArtifact?'物件 · ':'')+tiers[e.tier],text:e.summary,rank:e.name.toLowerCase().includes(q)?0:1});for(const e of t.events)if([e.title,e.summary,e.detail].join(' ').toLowerCase().includes(q))results.push({type:'event',id:e.id,tid:t.id,title:e.title,label:t.name+' · 事件',text:e.summary});for(const s of t.sources)if([s.title,s.author,s.note].join(' ').toLowerCase().includes(q))results.push({type:'source',id:s.id,tid:t.id,title:s.title,label:t.name+' · '+s.kind,text:s.note,href:s.url})}results.sort((a,b)=>(a.rank??1)-(b.rank??1));$('#search-results').innerHTML=`<div class="search-hint">找到 ${results.length} 条${results.length>60?'，显示前 60 条，请细化关键词':''}</div>`+(results.slice(0,60).map(r=>r.type==='source'?`<a class="search-result" href="${url(r.href)}" target="_blank" rel="noopener noreferrer"><strong>${esc(r.title)} ↗</strong><small>${esc(r.label)}</small><p>${esc(r.text.slice(0,100))}</p></a>`:`<button class="search-result" ${r.type==='tradition'?`data-go="${r.id}"`:r.type==='entity'?`data-entity="${r.id}"`:`data-event="${r.id}" data-tradition="${r.tid}"`}><strong>${esc(r.title)}</strong><small>${esc(r.label)}</small><p>${esc(r.text.slice(0,100))}</p></button>`).join('')||'<div class="empty-state">尚未找到这个词。可尝试别名、神职或相关故事。</div>')}
function openEvent(tid,id){$('#search-dialog').close();$('#detail-dialog').close();state.eventTier=0;state.pendingEvent=id;const target=`#tradition/${tid}/events`;if(location.hash===target)renderRoute(false);else location.hash=target}

function openAbout(){const s=stats();$('#detail-content').innerHTML=`<div class="dialog-head"><span class="eyebrow">EDITORIAL NOTES</span><button data-close="detail-dialog" aria-label="关闭编纂说明">×</button></div><div class="about-credits"><h2>关于这部神话图谱</h2><p>万神纪是一份以中文阅读为主的比较神话学习指南。它以主题笔记为起点，以在线原典、博物馆及研究资料补充、校正与展开。</p><h3>覆盖与分级</h3><p>当前收录 ${state.data.length} 个分区、${s.entities} 位主体、${s.events} 个事件、${s.artifacts} 件物品与 ${s.relations} 条人物关系。深度研读、专题探索、简明导览表示本站的编录密度；核心、重要、扩展表示学习路线中的叙事重要性。它们不是传统自身统一规定的等级，也不是穷尽目录。</p><h3>文本与信仰</h3><p>这里的「神话」用作文化与叙事研究概念，不判定现实宗教信仰的真伪。汉传佛教、道教、印度教及亚伯拉罕诸传统仍有多样的活态实践。不同年代、地域和宗派的观点并不总能合成一套体系。</p><p>《西游记》《封神演义》、亚瑟王传奇、但丁与弥尔顿等文学作品均按文本语境讨论。古代故事中的时间，不直接等同于事件的历史年代。引句与转述的范围可在各卷出处核对。</p><h3>地图与资料</h3><p>地图节点表示代表性文化地区；克苏鲁的紫色节点表示现代文学创作地。地图不宣称唯一发源地或文化边界；汉传佛教节点表示中国接受与发展区域，佛教起源于南亚。大陆轮廓采用 ${external('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth 公共领域数据')}；平面投影有形状失真，不作测距。图像优先选用公版或开放许可的历史作品，每幅保留来源、作者、时代解释与许可标记。</p><h3>图像档案</h3><ul>${state.data.flatMap(t=>(t.images||[]).map(i=>`<li>${esc(t.name)}：${external(i.pageUrl,i.title)}<br>${esc(i.credit)} · ${esc(i.license)}</li>`)).join('')}</ul><h3>本地记录</h3><p>学习进度、书签与笔记存于浏览器，无账号同步。清理浏览器数据会移除这些记录；可在「我的书签」导出。</p><p class="muted">编纂日期：2026 年 10 月 29 日。来源链接可能随馆藏网站调整而变化。</p></div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-go],[data-entity],[data-event],[data-bookmark],[data-close],[data-read],[data-filter],[data-mapmode],[data-action],[data-image]');if(!b)return;if(b.dataset.image){openImage(b.dataset.image);return}if(b.dataset.close){document.getElementById(b.dataset.close).close();return}if(b.dataset.entity){$('#search-dialog').close();openEntity(b.dataset.entity);return}if(b.dataset.event){openEvent(b.dataset.tradition,b.dataset.event);return}if(b.dataset.go){$('#search-dialog').close();state.entityQuery='';state.entityTier=0;go(b.dataset.go,b.dataset.tab||'worldview');return}if(b.dataset.bookmark){toggleBookmark(b.dataset.bookmark);return}if(b.dataset.read){const [id,tab]=b.dataset.read.split('/');markRead(id,tab);return}if(b.dataset.filter){state.filter=+b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',+x.dataset.filter===state.filter));renderTraditionCards();return}if(b.dataset.mapmode){state.mapMode=b.dataset.mapmode;$$('[data-mapmode]').forEach(x=>x.classList.toggle('active',x.dataset.mapmode===state.mapMode));renderMap();return}const action=b.dataset.action;if(action==='graph-in'||action==='graph-out'){const svg=$('#relation-graph'),v=svg.getAttribute('viewBox').split(' ').map(Number),w=Math.max(350,Math.min(+(svg.dataset.maxWidth||1600),v[2]*(action==='graph-in'?.8:1.25))),h=w*.7;svg.setAttribute('viewBox',[v[0]+(v[2]-w)/2,v[1]+(v[3]-h)/2,w,h].join(' '))}if(action==='about')openAbout();if(action==='map-plus'||action==='map-minus'){state.mapZoom=Math.max(.8,Math.min(3.5,state.mapZoom*(action==='map-plus'?1.2:1/1.2)));updateMapTransform()}if(action==='map-reset'){state.mapZoom=1;state.panX=state.panY=0;state.globeLon=30;state.globeLat=15;updateMapTransform()}if(action==='globe-spin'){state.spin=!state.spin;b.textContent=state.spin?'暂停自转':'开启自转'}if(action==='export-notes'){const data={title:'万神纪学习记录',date:new Date().toISOString(),bookmarks:state.bookmarks.map(entityById).filter(Boolean).map(({t,e})=>({id:e.id,name:e.name,tradition:t.name})),read:state.read,notes:safeRead('myth-notes','')},blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='万神纪-学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}});
document.addEventListener('pointerover',e=>{const n=e.target.closest('[data-preview]');if(n&&state.route==='atlas'&&state.selected!==n.dataset.preview)renderPreview(n.dataset.preview)});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[role="button"]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}if(e.key==='/'&&!/input|textarea|select/i.test(e.target.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();openSearch()}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.dataset.imagePage){const parent=e.target.parentElement;const fallback=document.createElement('div');fallback.className='image-fallback';fallback.innerHTML=`<span>图像暂时无法加载</span>${external(e.target.dataset.imagePage,'打开馆藏原页')}`;if(parent.tagName==='A'){parent.replaceChildren(fallback);fallback.innerHTML='<span>图像暂时无法加载<br>点击打开馆藏原页 ↗</span>'}else e.target.replaceWith(fallback)}},true);
$('#search-trigger').onclick=openSearch;$('#global-search').oninput=e=>renderSearch(e.target.value);
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
window.addEventListener('hashchange',()=>renderRoute());
async function init(){try{const cached=window.MYTH_ATLAS_CONTENT;const names=['data/china.json','data/core.json','data/others.json','data/cthulhu.json','assets/land.json','data/images.json','data/enrichment-china.json','data/enrichment-core.json','data/enrichment-others.json','data/enrichment-cthulhu.json'];const loaded=cached?[cached.china,cached.core,cached.others,cached.cthulhu||[],cached.land,cached.images,...(cached.enrichment?[cached.enrichment]:[])]:await Promise.all(names.map(async path=>{const r=await fetch(path);if(!r.ok){if(path.includes('enrichment-')||path.endsWith('images.json'))return{};throw new Error(path+' '+r.status)}return r.json()}));const [china,core,others,cthulhu,land,extra,...enrichmentParts]=loaded;const enrichment=Object.assign({},...enrichmentParts);state.data=[...china,...core,...others,...cthulhu].sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));state.land=land;for(const t of state.data){t.artifacts=t.artifacts||[];t.groups=t.groups||[];for(const a of t.artifacts)a.isArtifact=true;t.images=[...(extra[t.id]||[]),...(t.images||[])];t.cautions=t.cautions||[];t.reading=t.reading||[];t.quotes=t.quotes||[];for(const item of [...t.entities,...t.events,...t.artifacts]){const rich=enrichment[item.id]||{};item.images=rich.images||[];item.citations=rich.citations||[];item.imageReferences=rich.imageReferences||[];}const allImages=[...t.images,...t.entities.flatMap(mediaFor),...t.events.flatMap(mediaFor),...t.artifacts.flatMap(mediaFor)];t.images=[...new Map(allImages.map(img=>[img.local||img.url,img])).values()];t.entities.sort((a,b)=>a.tier-b.tier);t.artifacts.sort((a,b)=>a.tier-b.tier)}renderRoute()}catch(err){$('#main').innerHTML='<div class="loading"><img src="assets/emblem.svg" alt=""><p>图谱资料暂时未能载入。</p><p class="muted">请通过网站地址访问，或稍后刷新。</p><button class="button-outline" onclick="location.reload()">重新载入</button></div>';console.error(err)}}
init();


function groupSection(t){
  if(!t.groups.length)return '';
  return `<h3 class="subheading">体系与群像</h3><p class="controls-note">分组帮助梳理文本中的群体与叙事线，不表示所有时期都存在同一套组织。</p><div class="system-groups">${t.groups.map(g=>`<details class="system-group"><summary>${esc(g.title)}<span>${g.members.length} 位已收录主体</span></summary><p class="prose">${esc(g.summary)}</p><div class="sheet-links">${g.members.map(id=>{const e=entityById(id)?.e;return e?`<button data-entity="${id}">${portraitMarkup(e,'related-avatar')}${esc(e.name)} ${badge(e.tier)}</button>`:''}).join('')}</div>${sourceLink(t,g.source)}</details>`).join('')}</div>`;
}
function artifactLinks(t,id,event=false){
  const objects=state.data.flatMap(x=>x.artifacts).filter(a=>(event?a.events:a.owners).includes(id));
  if(!objects.length)return '';
  return `<section class="sheet-section"><h3>关联法宝与物件 <small>${objects.length}</small></h3><div class="artifact-link-grid">${objects.map(a=>`<button data-entity="${a.id}">${mediaFor(a)[0]?imageMarkup(mediaFor(a)[0]):'<span class="artifact-glyph">◇</span>'}<span><strong>${esc(a.name)}</strong><small>${tiers[a.tier]} · ${esc(a.kind)}</small></span></button>`).join('')}</div><p class="controls-note">包含使用、制作、保管、争夺或受其作用等联系，详见物件条目。</p></section>`;
}
function renderArtifacts(t){
  if(!t.artifacts.some(a=>a.kind===state.artifactKind))state.artifactKind='';
  const kinds=[...new Set(t.artifacts.map(a=>a.kind))],sourceIds=new Set(t.artifacts.flatMap(a=>a.sources));
  $('#chapter-content').innerHTML=`<div class="chapter-heading"><div><span class="eyebrow">06 / OBJECTS THAT CARRY STORIES</span><h2>${t.nature==='modern-literary'?'虚构文献与物件':'法宝、圣物与关键物件'}</h2><p>从一件物品，读懂力量、秩序与故事的转折。可按重要性和类型检索，再沿人物与事件继续阅读。</p></div></div><div class="toolbar"><label>重要性<select id="artifact-tier"><option value="0">全部物件</option>${[1,2,3].map(i=>`<option value="${i}" ${state.artifactTier===i?'selected':''}>${tiers[i]}物件</option>`).join('')}</select></label><label>类别<select id="artifact-kind"><option value="">全部类别</option>${kinds.map(k=>`<option value="${esc(k)}" ${k===state.artifactKind?'selected':''}>${esc(k)}</option>`).join('')}</select></label><label>文本与出处<select id="artifact-source"><option value="">全部出处</option>${t.sources.filter(x=>sourceIds.has(x.id)).map(x=>`<option value="${x.id}" ${x.id===state.artifactSource?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><input id="artifact-search" type="search" placeholder="物件名称、别名、关联人物或故事…" value="${esc(state.artifactQuery)}"><span class="entity-count" id="artifact-count"></span></div><div class="artifact-grid" id="artifact-grid"></div>`;
  $('#artifact-tier').onchange=e=>{state.artifactTier=+e.target.value;renderArtifactGrid(t)};
  $('#artifact-kind').onchange=e=>{state.artifactKind=e.target.value;renderArtifactGrid(t)};
  $('#artifact-source').onchange=e=>{state.artifactSource=e.target.value;renderArtifactGrid(t)};
  $('#artifact-search').oninput=e=>{state.artifactQuery=e.target.value;renderArtifactGrid(t)};
  renderArtifactGrid(t);
}
function renderArtifactGrid(t){
  const q=state.artifactQuery.trim().toLowerCase();
  const items=t.artifacts.filter(a=>(!state.artifactTier||a.tier===state.artifactTier)&&(!state.artifactKind||a.kind===state.artifactKind)&&(!state.artifactSource||a.sources.includes(state.artifactSource))&&(!q||[a.name,a.alias,a.kind,a.summary,a.detail,...a.owners.map(id=>entityById(id)?.e.name)].join(' ').toLowerCase().includes(q)));
  $('#artifact-count').textContent=`${items.length} / ${t.artifacts.length} 件物品`;
  $('#artifact-grid').innerHTML=items.map(a=>`<button class="artifact-card" data-entity="${a.id}"><div class="artifact-art">${mediaFor(a)[0]?imageMarkup(mediaFor(a)[0]):'<span aria-hidden="true">◇</span>'}${badge(a.tier)}${mediaFor(a)[0]?`<span class="artifact-image-kind">${imageRoles[mediaFor(a)[0].role]||'图像对照'}</span>`:''}</div><div class="artifact-copy"><small>${esc(a.kind)}</small><h3>${esc(a.name)}</h3><p>${esc(a.summary)}</p></div></button>`).join('')||'<div class="empty-state">当前筛选没有匹配物件。请调整关键词或分类。</div>';
}
function openArtifact(t,a){
  $('#detail-content').innerHTML=`<div class="dialog-head"><span class="eyebrow">${esc(t.name)} / ${esc(a.kind)}</span><button data-close="detail-dialog" aria-label="关闭物件详情">×</button></div><article class="entity-sheet"><div class="sheet-title"><div>${badge(a.tier)}<h2>${esc(a.name)}</h2><p class="sheet-alias">${esc(a.alias||a.kind)}</p></div><button class="button-outline ${state.bookmarks.includes(a.id)?'active':''}" data-bookmark="${a.id}">${state.bookmarks.includes(a.id)?'◆ 已收藏':'◇ 加入书签'}</button></div><p class="sheet-summary">${esc(a.summary)}</p>${itemGallery(a,'物件的形象与文献对照')}<p class="prose">${esc(a.detail)}</p>${citationSection(t,a)}${a.owners.length?`<section class="sheet-section"><h3>与谁相连</h3><div class="sheet-links">${a.owners.map(id=>{const e=entityById(id)?.e;return e?`<button data-entity="${id}">${portraitMarkup(e,'related-avatar')}${esc(e.name)}</button>`:''}).join('')}</div><p class="controls-note">关联可包括制造者、持有者、使用者与作用对象；不表示都拥有此物。</p></section>`:''}${a.events.length?`<section class="sheet-section"><h3>相关事件</h3><div class="sheet-links">${a.events.map(id=>{const f=eventById(id),e=f?.e;return e?`<button data-event="${id}" data-tradition="${f.t.id}">${esc(e.title)}</button>`:''}).join('')}</div></section>`:''}<details class="reading-fold"><summary>更多出处与阅读说明<span class="fold-cue">＋</span></summary><div class="fold-content">${a.sources.map(id=>sourceLink(t,id)).join('<br>')}<p class="controls-note">图像可为古代器物、历史插图或文本参照；具体关系见图注。不同文本中的同名物件未必是同一件。</p></div></details></article>`;
  const d=$('#detail-dialog');if(!d.open)d.showModal();d.scrollTop=0;
}

function readingFold(title,content,meta=''){return `<details class="reading-fold"><summary>${esc(title)}<span class="fold-cue">${esc(meta)} ＋</span></summary><div class="fold-content">${content}</div></details>`}
